/**
 * The catalog entries a JOINT can be built from — everything except the 三通件
 * (kind 'node').
 *
 * A node is a free part: it has no pair of mounting faces to be solved against,
 * so it is placed where the pointer is and never swapped into an existing joint.
 * The joint solvers read this list rather than `CONNECTORS` — the replace
 * pickers, and the kit editor's per-pattern groups. Offering a cube in any of
 * them would produce a part posed as an angle bracket: a rotation derived from
 * two faces it does not have, following profiles it is not bolted to.
 */
export const JOINT_CONNECTORS: DiyConnector[] = CONNECTORS.filter((c) => c.kind !== 'node');

/**
 * Angle covers (盖板) — catalog parts whose whole job is to hide a joint.
 *
 * Deliberately NOT in CONNECTORS: a connector is something the editor lets you
 * place and a kit bolts THROUGH, and a cover is neither. It rides along with
 * the joint that owns it (see AccessoryKit.cover), so it needs a lookup of its
 * own and must not turn up in the connector library or the parts count.
 */
export const CONNECTOR_COVERS: DiyConnector[] = [
  {
    id: '1.46.204.2828A',
    label: 'Angle Cover 28x28',
    desc: '角件盖板 · 锌合金',
    dim: '28x28',
    kind: 'zinc',
    stlUrl: '/connectors/1.46.204.2828A.stl',
    color: '#9aa0a6',
    extMm: 32,
    boxMm: { min: [0, 0, -14], max: [32, 32, 14] },
  },
];

const byId = new Map(CONNECTORS.map((c) => [c.id, c]));
const coverById_ = new Map(CONNECTOR_COVERS.map((c) => [c.id, c]));

/** Look up a connector catalog entry; unknown ids fall back to the cast bracket. */
export function connectorById(id?: string | null): DiyConnector {
  return (id && byId.get(id)) || CAST_CONNECTOR;
}

/**
 * Look up an angle cover by catalog id. Returns null rather than a fallback:
 * there is no "default cover" to substitute, and quietly drawing the wrong
 * cap over a joint would be worse than drawing none.
 */
export function coverById(id?: string | null): DiyConnector | null {
  return (id && coverById_.get(id)) || null;
}

// The cast bracket is NOT in CONNECTORS (it is the built-in default rather than
// a library entry), so the by-STL map has to add it back.
const byStlUrl = new Map([CAST_CONNECTOR, ...CONNECTORS].map((c) => [c.stlUrl, c]));

/**
 * Look up a connector by the STL it renders — the form a bracket instance
 * carries (`BracketInstance.stlUrl`), and the key a kit layout is scoped by.
 *
 * Unknown urls fall back to the cast bracket, matching `holePatternFor`'s
 * fallback: the default hole pattern IS the cast bracket's. Geometry and hole
 * pattern therefore can never be resolved from two different catalog entries.
 */
export function connectorByStlUrl(stlUrl?: string | null): DiyConnector {
  return (stlUrl && byStlUrl.get(stlUrl)) || CAST_CONNECTOR;
}
